     1→/**
     2→ * @module OpenAIRealtimeSession
     3→ *
     4→ * Represents ONE active OpenAI Realtime WebSocket conversation.
     5→ *
     6→ * ## Purpose
     7→ * Manages the lifecycle of a single WebSocket connection to the OpenAI
     8→ * Realtime API. Translates Voice Engine audio/text operations into the
     9→ * OpenAI Realtime protocol and emits strongly typed provider events.
    10→ *
    11→ * ## Ownership
    12→ * Created by `OpenAIRealtimeProvider.openSession()`. The caller owns the
    13→ * session and must call `close()` when the conversation ends.
    14→ *
    15→ * ## Thread Safety
    16→ * All public methods are async and must be awaited sequentially by the owner.
    17→ * The session does not acquire locks; the owner is responsible for sequencing.
    18→ *
    19→ * ## Lifecycle
    20→ * ```
    21→ * new OpenAIRealtimeSession()
    22→ *   └─► connect()        — WebSocket opens, session.created received
    23→ *         ├─► sendAudio()       — append PCM/G.711 chunks
    24→ *         ├─► sendText()        — inject text message
    25→ *         ├─► interrupt()       — cancel active response
    26→ *         ├─► updateInstructions() — update system prompt mid-call
    27→ *         ├─► updateTools()        — hot-swap available tools
    28→ *         └─► submitToolResult()   — send function call output
    29→ *   └─► close()          — graceful disconnect
    30→ * ```
    31→ */
    32→
    33→import { WebSocket } from 'ws';
    34→import type { OpenAIRealtimeConfig } from './OpenAIRealtimeConfig.js';
    35→import type { ILogger } from '../../logger/index.js';
    36→import type { IMetricsCollector } from '../../metrics/index.js';
    37→import type {
    38→  ClientEvent,
    39→  ServerEvent,
    40→  ServerEventType,
    41→  ServerEventMap,
    42→  Tool,
    43→  RealtimeSessionResource,
    44→} from './OpenAIRealtimeTypes.js';
    45→import type {
    46→  RealtimeProviderEvent,
    47→  RealtimeEventHandler,
    48→} from './OpenAIRealtimeEvents.js';
    49→import { ProviderError, ErrorCode } from '../../errors/index.js';
    50→import type { ConversationSessionContext } from './ConversationSessionContext.js';
    51→
    52→type SessionState = 'idle' | 'connecting' | 'connected' | 'closing' | 'closed';
    53→
    54→/**
    55→ * The public interface for a single OpenAI Realtime conversation session.
    56→ */
    57→export interface IOpenAIRealtimeSession {
    58→  /** Whether the WebSocket connection is currently open. */
    59→  readonly isConnected: boolean;
    60→  /** The OpenAI-assigned session ID, available after `connect()` resolves. */
    61→  readonly sessionId: string | null;
    62→  /**
    63→   * The live conversation session context (Policy + State engines), or null
    64→   * when the session was opened without a `policyContext`.
    65→   * Use this to dispatch signals (objections, pain points, etc.) at any time.
    66→   */
    67→  readonly conversationContext: ConversationSessionContext | null;
    68→
    69→  connect(): Promise<void>;
    70→  sendAudio(base64Chunk: string): void;
    71→  sendText(text: string): Promise<void>;
    72→  interrupt(): Promise<void>;
    73→  updateInstructions(instructions: string): Promise<void>;
    74→  updateTools(tools: readonly Tool[]): Promise<void>;
    75→  submitToolResult(callId: string, output: string): Promise<void>;
    76→  close(): Promise<void>;
    77→
    78→  on<K extends RealtimeProviderEvent['type']>(
    79→    type: K,
    80→    handler: RealtimeEventHandler<RealtimeProviderEvent & { type: K }>
    81→  ): void;
    82→  off<K extends RealtimeProviderEvent['type']>(
    83→    type: K,
    84→    handler: RealtimeEventHandler<RealtimeProviderEvent & { type: K }>
    85→  ): void;
    86→}
    87→
    88→/**
    89→ * Concrete implementation of a single OpenAI Realtime WebSocket session.
    90→ */
    91→export class OpenAIRealtimeSession implements IOpenAIRealtimeSession {
    92→  private readonly _config: OpenAIRealtimeConfig;
    93→  private readonly _logger: ILogger;
    94→  private readonly _metrics: IMetricsCollector;
    95→  private readonly _initialInstructions: string;
    96→
    97→  /** Optional conversation intelligence context wired at construction time. */
    98→  private readonly _conversationContext: ConversationSessionContext | null;
    99→
   100→  /** Rolling buffer of the last completed agent transcript (for question detection). */
   101→  private _lastAgentTranscript: string | null = null;
   102→
   103→  private _ws: WebSocket | null = null;
   104→  private _state: SessionState = 'idle';
   105→  private _sessionId: string | null = null;
   106→
   107→  private readonly _handlers = new Map<string, Set<RealtimeEventHandler>>();
   108→
   109→  /** [V2 TRACE] first-only guards */
   110→  private _traceFirstTranscript = true;
   111→  private _traceFirstAIResponse = true;
   112→
   113→  constructor(
   114→    config: OpenAIRealtimeConfig,
   115→    initialInstructions: string,
   116→    logger: ILogger,
   117→    metrics: IMetricsCollector,
   118→    conversationContext?: ConversationSessionContext
   119→  ) {
   120→    this._config = config;
   121→    this._conversationContext = conversationContext ?? null;
   122→    // If a conversation context is provided, it generates the full initial
   123→    // instruction (policy + live state section).  Otherwise fall back to the
   124→    // raw string passed by the caller.
   125→    this._initialInstructions = conversationContext
   126→      ? conversationContext.buildInitialInstruction()
   127→      : initialInstructions;
   128→    this._logger = logger.child({ component: 'OpenAIRealtimeSession' });
   129→    this._metrics = metrics;
   130→  }
   131→
   132→  get isConnected(): boolean {
   133→    return this._state === 'connected' && this._ws?.readyState === WebSocket.OPEN;
   134→  }
   135→
   136→  get sessionId(): string | null {
   137→    return this._sessionId;
   138→  }
   139→
   140→  get conversationContext(): ConversationSessionContext | null {
   141→    return this._conversationContext;
   142→  }
   143→
   144→  /**
   145→   * Opens the WebSocket connection and waits for the `session.created` event.
   146→   * @throws {ProviderError} if the connection cannot be established within the configured timeout.
   147→   */
   148→  async connect(): Promise<void> {
   149→    console.log(`[V2 TRACE] 6. OpenAIRealtimeSession.connect()  state=${this._state}`);
   150→    if (this._state !== 'idle') {
   151→      throw new ProviderError(
   152→        `OpenAIRealtimeSession.connect() called in invalid state: ${this._state}`,
   153→        ErrorCode.PROVIDER_UNAVAILABLE,
   154→        'openai-realtime'
   155→      );
   156→    }
   157→
   158→    this._state = 'connecting';
   159→    const url = `${this._config.realtimeURL}?model=${encodeURIComponent(this._config.model)}`;
   160→
   161→    await new Promise<void>((resolve, reject) => {
   162→      const timeout = setTimeout(() => {
   163→        reject(new ProviderError(
   164→          `OpenAI Realtime WebSocket connection timed out after ${this._config.connectTimeoutMs}ms`,
   165→          ErrorCode.PROVIDER_TIMEOUT,
   166→          'openai-realtime'
   167→        ));
   168→      }, this._config.connectTimeoutMs);
   169→
   170→      const ws = new WebSocket(url, {
   171→        headers: {
   172→          Authorization: `Bearer ${this._config.apiKey}`,
   173→        },
   174→      });
   175→
   176→      this._ws = ws;
   177→
   178→      ws.on('open', () => {
   179→        console.log(`[V2 TRACE] 7. Realtime websocket connected  url=${url}`);
   180→        this._logger.debug('WebSocket open — waiting for session.created');
   181→      });
   182→
   183→      ws.on('message', (data: Buffer | string) => {
   184→        const raw = typeof data === 'string' ? data : data.toString('utf-8');
   185→        let event: ServerEvent;
   186→        try {
   187→          event = JSON.parse(raw) as ServerEvent;
   188→        } catch {
   189→          this._logger.warn('Failed to parse server event', { raw: raw.slice(0, 200) });
   190→          return;
   191→        }
   192→
   193→        if (event.type === 'session.created') {
   194→          clearTimeout(timeout);
   195→          this._sessionId = event.session.id ?? null;
   196→          this._state = 'connected';
   197→          this._logger.info('OpenAI Realtime session created', { sessionId: this._sessionId });
   198→
   199→          this._sendEvent({
   200→            type: 'session.update',
   201→            session: this._buildSessionConfig(this._initialInstructions),
   202→          });
   203→
   204→          resolve();
   205→        }
   206→
   207→        this._handleServerEvent(event);
   208→      });
   209→
   210→      ws.on('error', (err: Error) => {
   211→        this._logger.error('WebSocket error', { message: err.message });
   212→        if (this._state === 'connecting') {
   213→          clearTimeout(timeout);
   214→          reject(new ProviderError(err.message, ErrorCode.PROVIDER_UNAVAILABLE, 'openai-realtime'));
   215→        }
   216→        this._emit({
   217→          type: 'realtime.error',
   218→          timestamp: Date.now(),
   219→          eventId: '',
   220→          errorType: 'websocket_error',
   221→          message: err.message,
   222→          fatal: true,
   223→        });
   224→      });
   225→
   226→      ws.on('close', (code: number, reason: Buffer) => {
   227→        this._state = 'closed';
   228→        this._emit({
   229→          type: 'realtime.disconnected',
   230→          timestamp: Date.now(),
   231→          eventId: '',
   232→          code,
   233→          reason: reason.toString('utf-8'),
   234→          wasClean: code === 1000,
   235→        });
   236→        this._logger.info('WebSocket closed', { code });
   237→      });
   238→    });
   239→  }
   240→
   241→  /**
   242→   * Appends a base64-encoded audio chunk to the input buffer.
   243→   * Fire-and-forget — does not wait for server acknowledgement.
   244→   */
   245→  sendAudio(base64Chunk: string): void {
   246→    this._sendEvent({ type: 'input_audio_buffer.append', audio: base64Chunk });
   247→    this._emit({
   248→      type: 'realtime.audio_sent',
   249→      timestamp: Date.now(),
   250→      eventId: '',
   251→      byteLength: base64Chunk.length,
   252→    });
   253→  }
   254→
   255→  /**
   256→   * Sends a text message into the conversation and triggers a response.
   257→   */
   258→  async sendText(text: string): Promise<void> {
   259→    this._assertConnected();
   260→    this._sendEvent({
   261→      type: 'conversation.item.create',
   262→      item: {
   263→        type: 'message',
   264→        role: 'user',
   265→        content: [{ type: 'input_text', text }],
   266→      },
   267→    });
   268→    this._sendEvent({ type: 'response.create' });
   269→  }
   270→
   271→  /**
   272→   * Cancels the current in-progress response (barge-in).
   273→   */
   274→  async interrupt(): Promise<void> {
   275→    this._assertConnected();
   276→    this._sendEvent({ type: 'response.cancel' });
   277→    this._sendEvent({ type: 'input_audio_buffer.clear' });
   278→    this._logger.debug('Sent interrupt (response.cancel + buffer clear)');
   279→  }
   280→
   281→  /**
   282→   * Hot-updates the system instructions for the current session.
   283→   */
   284→  async updateInstructions(instructions: string): Promise<void> {
   285→    this._assertConnected();
   286→    this._sendEvent({
   287→      type: 'session.update',
   288→      session: { instructions },
   289→    });
   290→  }
   291→
   292→  /**
   293→   * Hot-swaps the list of tools available to the model.
   294→   */
   295→  async updateTools(tools: readonly Tool[]): Promise<void> {
   296→    this._assertConnected();
   297→    this._sendEvent({
   298→      type: 'session.update',
   299→      session: { tools: tools as Tool[] },
   300→    });
   301→  }
   302→
   303→  /**
   304→   * Submits the result of a function call back to the session.
   305→   */
   306→  async submitToolResult(callId: string, output: string): Promise<void> {
   307→    this._assertConnected();
   308→    this._sendEvent({
   309→      type: 'conversation.item.create',
   310→      item: {
   311→        type: 'function_call_output',
   312→        call_id: callId,
   313→        output,
   314→      },
   315→    });
   316→    this._sendEvent({ type: 'response.create' });
   317→    this._emit({
   318→      type: 'realtime.tool_result',
   319→      timestamp: Date.now(),
   320→      eventId: '',
   321→      callId,
   322→      output,
   323→    });
   324→  }
   325→
   326→  /**
   327→   * Gracefully closes the WebSocket connection.
   328→   */
   329→  async close(): Promise<void> {
   330→    if (this._state === 'closed' || this._state === 'closing') return;
   331→    this._state = 'closing';
   332→    this._ws?.close(1000, 'Session closed by provider');
   333→    this._logger.info('OpenAI Realtime session closing');
   334→  }
   335→
   336→  on<K extends RealtimeProviderEvent['type']>(
   337→    type: K,
   338→    handler: RealtimeEventHandler<RealtimeProviderEvent & { type: K }>
   339→  ): void {
   340→    if (!this._handlers.has(type)) this._handlers.set(type, new Set());
   341→    this._handlers.get(type)!.add(handler as RealtimeEventHandler);
   342→  }
   343→
   344→  off<K extends RealtimeProviderEvent['type']>(
   345→    type: K,
   346→    handler: RealtimeEventHandler<RealtimeProviderEvent & { type: K }>
   347→  ): void {
   348→    this._handlers.get(type)?.delete(handler as RealtimeEventHandler);
   349→  }
   350→
   351→  // ─── Private ────────────────────────────────────────────────────────────────
   352→
   353→  private _buildSessionConfig(instructions: string): Partial<RealtimeSessionResource> {
   354→    return {
   355→      modalities: this._config.modalities as ('text' | 'audio')[],
   356→      instructions,
   357→      voice: this._config.voice,
   358→      input_audio_format: this._config.inputAudioFormat,
   359→      output_audio_format: this._config.outputAudioFormat,
   360→      input_audio_transcription: this._config.enableInputTranscription
   361→        ? { model: this._config.transcriptionModel }
   362→        : null,
   363→      turn_detection: this._config.turnDetection,
   364→      temperature: this._config.temperature,
   365→      max_response_output_tokens: this._config.maxResponseOutputTokens,
   366→    };
   367→  }
   368→
   369→  private _sendEvent(event: ClientEvent): void {
   370→    if (this._ws?.readyState !== WebSocket.OPEN) {
   371→      this._logger.warn('Attempted to send event on non-open WebSocket', { type: event.type });
   372→      return;
   373→    }
   374→    this._ws.send(JSON.stringify(event));
   375→  }
   376→
   377→  private _handleServerEvent(event: ServerEvent): void {
   378→    const ts = Date.now();
   379→
   380→    switch (event.type) {
   381→      case 'session.updated':
   382→        this._emit({ type: 'realtime.session_updated', timestamp: ts, eventId: event.event_id, session: event.session });
   383→        break;
   384→
   385→      case 'response.created':
   386→        if (this._traceFirstAIResponse) {
   387→          this._traceFirstAIResponse = false;
   388→          console.log(`[V2 TRACE] 13. First AI response received  responseId=${event.response.id}`);
   389→        }
   390→        this._emit({ type: 'realtime.response_started', timestamp: ts, eventId: event.event_id, responseId: event.response.id });
   391→        break;
   392→
   393→      case 'response.audio.delta':
   394→        this._emit({ type: 'realtime.audio_received', timestamp: ts, eventId: event.event_id, responseId: event.response_id, itemId: event.item_id, delta: event.delta });
   395→        break;
   396→
   397→      case 'response.audio_transcript.delta':
   398→        this._emit({ type: 'realtime.transcript_delta', timestamp: ts, eventId: event.event_id, responseId: event.response_id, itemId: event.item_id, delta: event.delta });
   399→        break;
   400→
   401→      case 'response.audio_transcript.done':
   402→        if (this._traceFirstTranscript) {
   403→          this._traceFirstTranscript = false;
   404→          console.log(`[V2 TRACE] 12. First transcript received  transcript="${(event.transcript ?? '').slice(0, 80)}"`);
   405→        }
   406→        // Capture completed agent transcript for question-detection in onAgentTurnCompleted()
   407→        this._lastAgentTranscript = event.transcript ?? null;
   408→        this._emit({ type: 'realtime.transcript_completed', timestamp: ts, eventId: event.event_id, responseId: event.response_id, itemId: event.item_id, transcript: event.transcript });
   409→        break;
   410→
   411→      case 'response.text.delta':
   412→        this._emit({ type: 'realtime.response_delta', timestamp: ts, eventId: event.event_id, responseId: event.response_id, itemId: event.item_id, delta: event.delta });
   413→        break;
   414→
   415→      case 'response.done': {
   416→        const responseStatus = event.response.status as 'completed' | 'cancelled' | 'failed' | 'incomplete';
   417→        this._emit({
   418→          type: 'realtime.response_completed',
   419→          timestamp: ts,
   420→          eventId: event.event_id,
   421→          responseId: event.response.id,
   422→          status: responseStatus,
   423→          totalTokens: event.response.usage?.total_tokens ?? 0,
   424→          inputTokens: event.response.usage?.input_tokens ?? 0,
   425→          outputTokens: event.response.usage?.output_tokens ?? 0,
   426→        });
   427→
   428→        // ── Conversation State: record agent turn & dynamically update instructions ──
   429→        // Only process completed (non-cancelled, non-failed) turns so interruptions
   430→        // don't count as full agent turns.
   431→        if (this._conversationContext && responseStatus === 'completed') {
   432→          const result = this._conversationContext.onAgentTurnCompleted(
   433→            this._lastAgentTranscript ?? undefined
   434→          );
   435→          this._lastAgentTranscript = null;
   436→
   437→          if (result.stateChanged && result.updatedInstruction) {
   438→            this._logger.debug(
   439→              'ConversationState changed — updating OpenAI session instructions',
   440→              { stage: result.currentStageLabel }
   441→            );
   442→            // Hot-update instructions without reconnecting
   443→            this._sendEvent({
   444→              type: 'session.update',
   445→              session: { instructions: result.updatedInstruction },
   446→            });
   447→          }
   448→        }
   449→        break;
   450→      }
   451→
   452→      case 'response.function_call_arguments.done':
   453→        this._emit({ type: 'realtime.tool_call', timestamp: ts, eventId: event.event_id, responseId: event.response_id, itemId: event.item_id, callId: event.call_id, functionName: event.name, arguments: event.arguments });
   454→        break;
   455→
   456→      case 'input_audio_buffer.speech_started':
   457→        this._emit({ type: 'realtime.speech_started', timestamp: ts, eventId: event.event_id, itemId: event.item_id, audioStartMs: event.audio_start_ms });
   458→        // ── Conversation State: record barge-in interruption ──────────────────
   459→        if (this._conversationContext) {
   460→          this._conversationContext.onCustomerInterrupted();
   461→        }
   462→        break;
   463→
   464→      case 'input_audio_buffer.speech_stopped':
   465→        this._emit({ type: 'realtime.speech_stopped', timestamp: ts, eventId: event.event_id, itemId: event.item_id, audioEndMs: event.audio_end_ms });
   466→        break;
   467→
   468→      case 'rate_limits.updated':
   469→        this._emit({ type: 'realtime.rate_limit', timestamp: ts, eventId: event.event_id, rateLimits: event.rate_limits });
   470→        break;
   471→
   472→      case 'error':
   473→        this._logger.error('OpenAI Realtime server error', { code: event.error.code, message: event.error.message });
   474→        this._emit({ type: 'realtime.error', timestamp: ts, eventId: event.event_id, errorType: event.error.type, errorCode: event.error.code, message: event.error.message, fatal: false });
   475→        break;
   476→
   477→      default:
   478→        break;
   479→    }
   480→  }
   481→
   482→  private _emit(event: RealtimeProviderEvent): void {
   483→    const handlers = this._handlers.get(event.type);
   484→    if (!handlers) return;
   485→    Array.from(handlers).forEach((handler) => {
   486→      try {
   487→        handler(event);
   488→      } catch (err) {
   489→        this._logger.warn('RealtimeSession event handler threw', { type: event.type, error: String(err) });
   490→      }
   491→    });
   492→  }
   493→
   494→  private _assertConnected(): void {
   495→    if (!this.isConnected) {
   496→      throw new ProviderError(
   497→        'OpenAIRealtimeSession is not connected',
   498→        ErrorCode.PROVIDER_UNAVAILABLE,
   499→        'openai-realtime'
   500→      );
   501→    }
   502→  }
   503→}
