     1→/**
     2→ * @module OpenAIRealtimeTypes
     3→ *
     4→ * Internal types for the OpenAI Realtime WebSocket API.
     5→ *
     6→ * ## Purpose
     7→ * Provides strongly typed models for every client→server and server→client
     8→ * event on the OpenAI Realtime WebSocket endpoint. Nothing outside this
     9→ * provider module should depend on these types.
    10→ *
    11→ * ## Ownership
    12→ * Owned exclusively by the OpenAI provider. No Voice Engine module outside
    13→ * `server/voice-engine/providers/openai/` may import from this file.
    14→ *
    15→ * ## References
    16→ * https://platform.openai.com/docs/api-reference/realtime
    17→ */
    18→
    19→// ─── Audio Format ─────────────────────────────────────────────────────────────
    20→
    21→export type RealtimeAudioFormat = 'pcm16' | 'g711_ulaw' | 'g711_alaw';
    22→
    23→// ─── Voice ────────────────────────────────────────────────────────────────────
    24→
    25→export type RealtimeVoice =
    26→  | 'alloy'
    27→  | 'ash'
    28→  | 'ballad'
    29→  | 'coral'
    30→  | 'echo'
    31→  | 'fable'
    32→  | 'onyx'
    33→  | 'nova'
    34→  | 'sage'
