    37→
    38→// ─── Turn Detection ───────────────────────────────────────────────────────────
    39→
    40→export interface ServerVADTurnDetection {
    41→  readonly type: 'server_vad';
    42→  readonly threshold?: number;
    43→  readonly prefix_padding_ms?: number;
