    51→  readonly create_response?: boolean;
    52→  readonly interrupt_response?: boolean;
    53→}
    54→
    55→export type TurnDetection = ServerVADTurnDetection | SemanticVADTurnDetection;
    56→
    57→// ─── Content Parts ────────────────────────────────────────────────────────────
    58→
    59→export interface TextContentPart {
    60→  readonly type: 'text';
    61→  readonly text: string;
    62→}
    63→
    64→export interface InputTextContentPart {
    65→  readonly type: 'input_text';
