   284→  /**
   285→   * Opens a new OpenAI Realtime WebSocket session for a live conversation.
   286→   * The caller must call `session.connect()` then `session.close()` when done.
   287→   *
   288→   * ## With Conversation Intelligence (recommended)
   289→   * Pass `options.policyContext` to activate the Policy Engine and State Engine.
   290→   * The session will generate its own initial instruction and update it
   291→   * automatically after every completed agent turn — no reconnection required.
   292→   *
   293→   * ## Signal injection after session creation
   294→   * ```ts
   295→   * const session = provider.openSession({ policyContext: ctx });
   296→   * await session.connect();
   297→   *
   298→   * // Inject a pain point discovered from the customer's speech
   299→   * session.conversationContext?.dispatchSignal(
   300→   *   Signals.painPointIdentified('Manual outreach is too slow')
   301→   * );
   302→   *
   303→   * // Inject an objection
   304→   * session.conversationContext?.dispatchSignal(
   305→   *   Signals.objectionRaised('price', "Seems expensive.")
   306→   * );
   307→   * ```
   308→   *
   309→   * @param options - Instructions (or policyContext) and optional tools.
   310→   * @returns An unconnected `IOpenAIRealtimeSession` ready to be connected.
   311→   */
   312→  openSession(options: OpenSessionOptions): IOpenAIRealtimeSession {
   313→    // Build a ConversationSessionContext when the caller supplies a policy
   314→    // context.  This activates the Policy Engine + State Engine for the call.
   315→    let conversationContext: ConversationSessionContext | undefined;
   316→
   317→    if (options.policyContext) {
   318→      conversationContext = new ConversationSessionContext({
   319→        policyContext: options.policyContext,
   320→        preloadedMemory: options.preloadedMemory,
   321→      });
   322→      this._logger.debug(
   323→        'OpenAI Realtime session created with Conversation Intelligence',
   324→        {
   325→          agentName: options.policyContext.agentName,
   326→          campaignGoal: options.policyContext.campaignGoal,
   327→          hasCaller: !!options.policyContext.caller,
   328→        }
   329→      );
   330→    } else {
   331→      this._logger.debug('OpenAI Realtime session created (legacy mode — no policy context)');
   332→    }
   333→
   334→    const session = new OpenAIRealtimeSession(
   335→      this._config,
   336→      options.instructions,
   337→      this._logger,
   338→      this._metrics,
   339→      conversationContext
   340→    );
   341→
   342→    return session;
   343→  }
