   228→
   229→    // Flush the engine pipeline (drain any buffered frames)
   230→    const flushResult = this._audioEngine.flushOutbound();
   231→
   232→    // Deliver any remaining frames before clearing
   233→    for (const scheduled of flushResult.chunksToSend) {
   234→      this._transport.sendAudio(this._sessionId, scheduled as AudioChunk);
   235→    }
   236→
   237→    // Clear transport buffer — stops audio playback at the telephony provider
   238→    this._transport.sendClear(this._sessionId);
   239→
   240→    this._logger.debug('OutboundAudioFlow: outbound flushed and transport cleared', {
   241→      flushedChunks: flushResult.chunksToSend.length,
   242→    });
   243→  }
