   246→
   247→  /**
   248→   * Builds an immutable outbound `AudioChunk` from a provider audio delta.
   249→   *
   250→   * @param base64Delta - Base64-encoded audio from the provider.
   251→   * @param timestamp   - Wall-clock timestamp of the event.
   252→   */
   253→  private _buildChunk(base64Delta: string, timestamp: number): Readonly<AudioChunk> {
   254→    const { sampleRate, encoding } = this._config.audioFormat;
   255→    const byteLength = Math.floor(base64Delta.length * 0.75);
   256→    const durationMs = sampleRate > 0
   257→      ? Math.round((byteLength / sampleRate) * 1000)
   258→      : 0;
   259→
   260→    return createAudioChunk({
   261→      sequence: this._chunkSequence++,
   262→      timestamp,
   263→      sampleRate,
   264→      encoding,
   265→      durationMs,
   266→      payload: base64Delta,
   267→      payloadFormat: 'base64',
   268→      direction: 'outbound',
   269→    });
   270→  }
