    50→  ExotelStartMessage,
    51→  ExotelMediaMessage,
    52→  ExotelMarkMessage,
    53→  ExotelStopMessage,
    54→  ExotelDtmfMessage,
    55→  ExotelHeartbeatMessage,
    56→} from './ExotelMessages.js';
    57→import {
    58→  decodeExotelMessage,
    59→  normaliseMediaFormat,
    60→  extractStreamSid,
    61→  extractMediaPayload,
    62→  extractTrackId,
    63→  encodeMediaMessage,
    64→  encodeMarkMessage,
    65→  encodeClearMessage,
    66→  isValidBase64Payload,
    67→} from './ExotelProtocol.js';
    68→
    69→// ─── Per-Session Audio Context ────────────────────────────────────────────────
    70→
    71→/**
    72→ * Mutable audio format state learned from the `start` message.
    73→ * Stored in a `WeakMap` keyed by `TransportSession` to avoid coupling.
    74→ */
    75→interface SessionAudioContext {
    76→  encoding: string;
    77→  sampleRate: number;
    78→  channels: number;
    79→  streamSid: string;
    80→}
    81→
    82→// ─── Implementation ───────────────────────────────────────────────────────────
    83→
    84→/**
    85→ * Production implementation of `ITransportAdapter` for the Exotel protocol.
    86→ */
    87→export class ExotelAdapter implements ITransportAdapter {
    88→  readonly name = 'exotel';
    89→
    90→  private readonly _logger: ILogger;
    91→
    92→  /**
    93→   * Per-session audio context. WeakMap ensures sessions can be GC'd without
    94→   * requiring explicit cleanup.
    95→   */
    96→  private readonly _audioContexts = new WeakMap<
    97→    TransportSession,
    98→    SessionAudioContext
    99→  >();
   100→
   101→  constructor(logger: ILogger) {
   102→    this._logger = logger.child({ component: 'ExotelAdapter' });
   103→  }
   104→
   105→  // ─── ITransportAdapter ─────────────────────────────────────────────────────
   106→
   107→  handleMessage(
   108→    raw: string,
   109→    session: TransportSession,
   110→    emit: TransportEventEmitter
   111→  ): void {
   112→    const msg = decodeExotelMessage(raw);
   113→    const { sessionId, callSid } = session.id;
   114→    const now = Date.now();
   115→
   116→    switch (msg.event) {
   117→      case 'connected':
   118→        this._logger.debug('Exotel connected handshake received', { sessionId });
   119→        // The real streamSid arrives in the 'start' message.
   120→        break;
   121→
   122→      case 'start': {
   123→        const start = msg as ExotelStartMessage;
   124→        const streamSid = extractStreamSid(start as unknown as Record<string, unknown>);
   125→        const fmt = normaliseMediaFormat(start);
   126→
   127→        // Mutate the immutable metadata's streamId field via a local context map.
   128→        // (The metadata object itself is frozen; we track streamId separately.)
   129→        const ctx: SessionAudioContext = {
   130→          encoding: fmt.encoding,
   131→          sampleRate: fmt.sampleRate,
   132→          channels: fmt.channels,
   133→          streamSid,
   134→        };
   135→        this._audioContexts.set(session, ctx);
   136→
   137→        // Patch the session metadata streamId so the gateway can use it for
   138→        // outbound sends. We use Object.defineProperty to bypass the frozen
   139→        // metadata field — this is the ONLY place this bypass is permitted.
   140→        try {
   141→          Object.defineProperty(session.metadata, 'streamId', {
   142→            value: streamSid,
   143→            writable: false,
   144→            configurable: true,
   145→          });
   146→        } catch {
   147→          // metadata may be fully frozen in test environments; gracefully skip.
   148→        }
   149→
   150→        this._logger.info('Exotel stream started', {
   151→          sessionId,
   152→          callSid,
   153→          streamSid,
   154→          encoding: fmt.encoding,
   155→          sampleRate: fmt.sampleRate,
   156→        });
   157→
   158→        emit({
   159→          type: 'transport.connected',
   160→          timestamp: now,
   161→          sessionId,
   162→          callSid,
   163→          protocol: 'websocket',
   164→          streamId: streamSid,
   165→          remoteAddress: session.metadata.remoteAddress,
   166→        });
   167→        break;
   168→      }
   169→
   170→      case 'media': {
   171→        const media = msg as ExotelMediaMessage;
   172→        const payload = extractMediaPayload(media);
   173→
   174→        if (!payload || !isValidBase64Payload(payload)) {
   175→          this._logger.debug('Exotel media message with empty payload — skipped', {
   176→            sessionId,
   177→          });
   178→          break;
   179→        }
   180→
   181→        const ctx = this._resolveAudioContext(session);
   182→        const seq = session.nextInboundSequence(now);
   183→
   184→        emit({
   185→          type: 'transport.audio_received',
   186→          timestamp: now,
   187→          sessionId,
   188→          callSid,
   189→          base64Payload: payload,
   190→          encoding: ctx.encoding,
   191→          sampleRate: ctx.sampleRate,
   192→          sequence: seq,
   193→          trackId: extractTrackId(media),
   194→        });
   195→        break;
   196→      }
   197→
   198→      case 'mark': {
   199→        const mark = msg as ExotelMarkMessage;
   200→        emit({
   201→          type: 'transport.mark_acknowledged',
   202→          timestamp: now,
   203→          sessionId,
   204→          callSid,
   205→          name: mark.mark?.name ?? '',
   206→        });
   207→        break;
   208→      }
   209→
   210→      case 'stop': {
   211→        const stop = msg as ExotelStopMessage;
   212→        this._logger.info('Exotel stop received — call ended', {
   213→          sessionId,
   214→          callSid,
   215→          streamSid: stop.streamSid,
   216→        });
   217→        emit({
   218→          type: 'transport.call_ended',
   219→          timestamp: now,
   220→          sessionId,
   221→          callSid,
   222→          reason: 'caller_hung_up',
   223→        });
   224→        break;
   225→      }
   226→
   227→      case 'dtmf': {
   228→        const dtmf = msg as ExotelDtmfMessage;
   229→        emit({
   230→          type: 'transport.dtmf_received',
   231→          timestamp: now,
   232→          sessionId,
   233→          callSid,
   234→          digit: dtmf.dtmf?.digit ?? '',
   235→          durationMs: Number(dtmf.dtmf?.duration ?? 0),
   236→        });
   237→        break;
   238→      }
   239→
   240→      case 'heartbeat':
   241→      case 'ping': {
   242→        const hb = msg as ExotelHeartbeatMessage;
   243→        this._logger.debug('Exotel heartbeat received', {
   244→          sessionId,
   245→          seq: hb.sequenceNumber,
   246→        });
   247→        emit({
   248→          type: 'transport.heartbeat',
   249→          timestamp: now,
   250→          sessionId,
   251→          callSid,
   252→          rttMs: null,
   253→        });
   254→        break;
   255→      }
   256→
   257→      default:
   258→        // Unknown messages must never crash the session.
   259→        this._logger.debug('Exotel unknown message type — ignored', {
   260→          sessionId,
   261→          event: msg.event,
   262→        });
   263→        break;
   264→    }
   265→  }
   266→
   267→  encodeOutboundAudio(chunk: AudioChunk, streamId: string): string {
   268→    const payload =
   269→      typeof chunk.payload === 'string'
   270→        ? chunk.payload
   271→        : Buffer.from(chunk.payload).toString('base64');
   272→
   273→    return encodeMediaMessage(streamId, payload);
   274→  }
   275→
   276→  encodeMark(streamId: string, name: string): string {
   277→    return encodeMarkMessage(streamId, name);
   278→  }
   279→
   280→  encodeClear(streamId: string): string {
   281→    return encodeClearMessage(streamId);
   282→  }
   283→
   284→  // ─── Private Helpers ────────────────────────────────────────────────────────
   285→
   286→  /**
   287→   * Returns the audio context for a session, falling back to μ-law 8 kHz if
   288→   * no `start` message has been received yet (should not happen in practice).
   289→   */
   290→  private _resolveAudioContext(session: TransportSession): SessionAudioContext {
   291→    return (
   292→      this._audioContexts.get(session) ?? {
   293→        encoding: 'mulaw',
   294→        sampleRate: 8000,
   295→        channels: 1,
   296→        streamSid: session.metadata.streamId,
   297→      }
   298→    );
   299→  }
   300→}
   301→

