app.post("/api/auth/register", async (req, res) => {
  try {
    const data = insertUserSchema.parse(req.body);
    const existingUser = await storage.getUserByEmail(data.email);
    if (existingUser) {
      return res.status(400).json({ message: "Email already in use" });
    }
    const user = await storage.createUser(data);

    // Auto-assign subscription if a plan was selected during registration
    if (data.selectedPlanId) {
      const plan = await storage.getPlan(data.selectedPlanId);
      if (plan) {
        const status = plan.price === 0 ? "Active" : "Pending";
        await storage.updateUserSubscription(user._id, {
          plan: plan.name,
          status,
          monthlyCallCredits: plan.price === 0 ? plan.credits : 0,
          creditsUsed: 0,
          renewalDate: plan.price === 0
            ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
            : undefined,
          joinedDate: new Date(),
        });
      }
    }

    res.status(201).json({ user });
  } catch (error: any) {
    res.status(400).json({ message: error.message });
  }
});

